// QuotaBird's Lambda: the AI pages (Ask Mark, Meeting Prep, Account Plan, Update Upward). No npm packages.
// The routes and Mark's persona live in quotabird.mjs, the playbooks in quotabird-playbooks.mjs, and the tool
// list in quotabird-catalog.mjs (generated by the site build). Deploy all four files.
//
// POST { "kind": "qb_mark" | "qb_coach" | "qb_route" | "qb_explain" | "qb_meeting_prep" | "qb_account_plan"
//        | "qb_update_upward", ... }. See quotabird.mjs. The site sends text/plain bodies (no CORS preflight).
// GET returns a small health check: { ok, service, version, catalog, model, ready, stream }.
//
// AWS settings: runtime Node.js 20 or later, Handler index.handler, timeout 30 seconds, memory 256 MB.
// The Function URL's invoke mode is RESPONSE_STREAM: index.handler streams the chat and writes every other
// answer whole. (index.streamingHandler is the same function under its old name. If the URL ever goes back to
// BUFFERED, set the Handler to index.bufferedHandler, which answers plain JSON.)
// CORS is set on the Function URL in the AWS console, so this code adds no CORS headers by default.
//
// Environment variables:
//   GEMINI_API_KEY             required
//   GEMINI_MODEL               default gemini-3.5-flash-lite
//   QB_GEMINI_MODEL            optional: overrides GEMINI_MODEL
//   ALLOWED_ORIGINS            comma list, e.g. https://quotabird.com,https://www.quotabird.com (default *)
//   QB_RATE_LIMIT_PER_MINUTE   requests per visitor (IP), default 10
//   QB_RATE_LIMIT_PER_HOUR     requests per visitor (IP), default 60
//   GEMINI_TIMEOUT_MS, BOT_USER_AGENT, SEND_CORS_HEADERS   optional
//
// Privacy: nothing here logs or stores anything typed on QuotaBird. Keep it that way, or change the site's copy
// ("Nothing you type is stored").

import { handleQuotaBird, QB_VERSION, QB_KINDS } from "./quotabird.mjs";
import { CATALOG_BUILD } from "./quotabird-catalog.mjs";

const env = process.env;

// AWS adds the CORS headers when they're set on the Function URL; adding our own as well makes browsers reject
// the duplicates. Opt in with SEND_CORS_HEADERS=true.
if (env.SEND_CORS_HEADERS === undefined) env.SEND_CORS_HEADERS = "false";

function clampInt(v, def, min, max) {
  const n = Number.parseInt(v, 10);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : def;
}

const MODEL = env.QB_GEMINI_MODEL || env.GEMINI_MODEL || "gemini-3.5-flash-lite";
const GEMINI_TIMEOUT_MS = clampInt(env.GEMINI_TIMEOUT_MS, 20000, 5000, 25000);
const PER_MINUTE = clampInt(env.QB_RATE_LIMIT_PER_MINUTE, 10, 1, 1000);
const PER_HOUR = clampInt(env.QB_RATE_LIMIT_PER_HOUR, 60, 1, 10000);
const MAX_BODY = 16_000;   // the workflow pages carry pasted notes; the chat sends its last 16 turns
const BOT_UA = env.BOT_USER_AGENT || `QuotaBird/${QB_VERSION} (+https://quotabird.com)`;
const GEMINI = (method) => `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(MODEL)}:${method}`;

function tryJson(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch { return null; }
}

function parseModelJson(text) {
  const cleaned = String(text || "").replace(/```json\s*/gi, "").replace(/```/g, "").trim();
  const direct = tryJson(cleaned);
  if (direct) return direct;
  const a = cleaned.indexOf("{"), b = cleaned.lastIndexOf("}");
  return a >= 0 && b > a ? tryJson(cleaned.slice(a, b + 1)) : null;
}

const geminiBody = (system, userText, schema, maxOutputTokens) => JSON.stringify({
  systemInstruction: { parts: [{ text: system }] },
  // userText is one user turn, or a ready-made contents array for a multi-turn chat
  contents: Array.isArray(userText) ? userText : [{ role: "user", parts: [{ text: userText }] }],
  generationConfig: { responseMimeType: "application/json", ...(schema ? { responseJsonSchema: schema } : {}), maxOutputTokens },
});
const geminiHeaders = () => ({ "Content-Type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY, "User-Agent": BOT_UA });
const BLOCKED = (data, cand) => data?.promptFeedback?.blockReason || cand?.finishReason === "SAFETY" || cand?.finishReason === "PROHIBITED_CONTENT";
const textOf = (cand) => (cand?.content?.parts || []).filter((p) => !p.thought && typeof p.text === "string").map((p) => p.text).join("");
const ERR = {
  timeout: [504, { error: "That took too long. Try again." }],
  network: [502, { error: "Couldn't reach the AI. Try again in a moment." }],
  busy: [503, { error: "The AI is busy right now. Try again in a minute." }],
  upstream: [502, { error: "The AI is having a moment. Try again." }],
  blocked: [422, { error: "The AI wouldn't touch that one. Try rewording it." }],
  garbled: [502, { error: "The answer came back garbled. Try again." }],
};

// One Gemini call, structured output. Returns { json } or { fail: [status, body] }.
export async function geminiJson(system, userText, schema, maxOutputTokens, opts = {}) {
  const call = async (withSchema) => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), Math.min(opts.timeout || GEMINI_TIMEOUT_MS, 27000));
    try {
      const res = await fetch(GEMINI("generateContent"), { method: "POST", headers: geminiHeaders(), body: geminiBody(system, userText, withSchema ? schema : null, maxOutputTokens), signal: ctrl.signal });
      return { status: res.status, text: await res.text() };
    } catch (e) { return { error: e?.name === "AbortError" ? "timeout" : "network" }; }
    finally { clearTimeout(timer); }
  };
  let r = await call(true);
  if (r.status === 400 && /schema/i.test(r.text)) r = await call(false);
  if (r.error) return { fail: ERR[r.error] };
  if (r.status === 429) return { fail: ERR.busy };
  if (r.status !== 200) return { fail: ERR.upstream };
  const data = tryJson(r.text);
  const cand = data?.candidates?.[0];
  if (BLOCKED(data, cand)) return { fail: ERR.blocked };
  const json = parseModelJson(textOf(cand));
  return json ? { json } : { fail: ERR.garbled };
}

// The same call, streamed (the chat): Gemini's server-sent events, each carrying a piece of the JSON answer,
// handed to onText as they arrive. Same model, schema and errors as geminiJson; a schema refusal falls back to it.
export async function geminiStream(system, userText, schema, maxOutputTokens, onText, opts = {}) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), Math.min(opts.timeout || GEMINI_TIMEOUT_MS, 27000));
  const failed = (e) => ({ fail: e?.name === "AbortError" ? ERR.timeout : ERR.network });
  let res;
  try { res = await fetch(GEMINI("streamGenerateContent") + "?alt=sse", { method: "POST", headers: geminiHeaders(), body: geminiBody(system, userText, schema, maxOutputTokens), signal: ctrl.signal }); }
  catch (e) { clearTimeout(timer); return failed(e); }
  if (res.status !== 200) {
    const text = await res.text().catch(() => "");
    clearTimeout(timer);
    if (res.status === 400 && /schema/i.test(text)) return geminiJson(system, userText, schema, maxOutputTokens, opts);
    return { fail: res.status === 429 ? ERR.busy : ERR.upstream };
  }
  let all = "", pending = "", blocked = false;
  try {
    const reader = res.body.getReader(), dec = new TextDecoder();
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      pending += dec.decode(value, { stream: true });
      let nl;
      while ((nl = pending.indexOf("\n")) >= 0) {
        const line = pending.slice(0, nl).trim(); pending = pending.slice(nl + 1);
        if (!line.startsWith("data:")) continue;
        const d = tryJson(line.slice(5).trim()); if (!d) continue;
        const cand = d.candidates?.[0];
        if (BLOCKED(d, cand)) blocked = true;
        const t = textOf(cand);
        if (t) { all += t; onText(t); }
      }
    }
  } catch (e) { clearTimeout(timer); return failed(e); }
  clearTimeout(timer);
  if (blocked) return { fail: ERR.blocked };
  const json = parseModelJson(all);
  return json ? { json } : { fail: ERR.garbled };
}

// Per-visitor rate limit, in this instance's memory (it resets when the instance does; that's fine for this).
const hits = new Map();
function rateLimited(ip) {
  const now = Date.now();
  const mKey = `${ip}:m:${Math.floor(now / 60_000)}`, hKey = `${ip}:h:${Math.floor(now / 3_600_000)}`;
  const m = (hits.get(mKey) || 0) + 1, h = (hits.get(hKey) || 0) + 1;
  if (hits.size > 10_000) hits.clear();
  hits.set(mKey, m); hits.set(hKey, h);
  return m > PER_MINUTE || h > PER_HOUR;
}

const allowedOrigins = () => (env.ALLOWED_ORIGINS || "*").split(",").map((s) => s.trim()).filter(Boolean);
function corsHeaders(origin) {
  if (env.SEND_CORS_HEADERS === "false") return {};
  const allowed = allowedOrigins();
  const allow = allowed.includes("*") ? "*" : allowed.includes(origin) ? origin : allowed[0];
  return { "Access-Control-Allow-Origin": allow, "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "content-type", "Access-Control-Max-Age": "86400", Vary: "Origin" };
}

// The request logic. `sink` is passed by the streaming entry point: with it, the chat writes its answer as it
// comes; without it (index.bufferedHandler), every answer is plain JSON.
export const bufferedHandler = async (event = {}, _context, sink = null) => {
  const headersIn = Object.fromEntries(Object.entries(event.headers || {}).map(([k, v]) => [k.toLowerCase(), v]));
  const origin = headersIn.origin || "";
  const method = event.requestContext?.http?.method || event.httpMethod || "POST";
  const ip = event.requestContext?.http?.sourceIp || event.requestContext?.identity?.sourceIp || "unknown";
  const respond = (statusCode, body) => ({
    statusCode,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...corsHeaders(origin) },
    body: body === "" ? "" : JSON.stringify(body),
  });

  if (method === "OPTIONS") return respond(204, "");
  const allowed = allowedOrigins();
  if (origin && !allowed.includes("*") && !allowed.includes(origin)) return respond(403, { error: "Origin not allowed." });
  if (method === "GET") return respond(200, { ok: true, service: "quotabird", version: QB_VERSION, catalog: CATALOG_BUILD, model: MODEL, ready: Boolean(env.GEMINI_API_KEY), stream: Boolean(sink) });
  if (method !== "POST") return respond(405, { error: "Use POST." });

  let raw = event.body || "";
  if (event.isBase64Encoded) raw = Buffer.from(raw, "base64").toString("utf8");
  if (raw.length > MAX_BODY) return respond(413, { error: "Request too large." });
  const body = tryJson(raw);
  if (!body || !QB_KINDS.includes(body.kind)) return respond(400, { error: "Unknown request." });
  if (rateLimited(ip)) return respond(429, { error: "That's a lot of questions in a short time. Give it a few minutes." });

  const stream = sink && body.stream === true ? {
    start: (status) => sink.start(status, { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store", ...corsHeaders(origin) }),
    write: (text) => sink.write(text),
  } : null;
  const [status, payload] = await handleQuotaBird(body, { gemini: geminiJson, geminiStream, stream, ready: Boolean(env.GEMINI_API_KEY) });
  if (status === 0) return { streamed: true };   // already written to the stream
  return respond(status, payload);
};

// The entry point Lambda calls (Function URL in RESPONSE_STREAM mode). Every request runs through the logic above;
// the chat streams, and anything else is written whole: its status and headers, then its body.
// The status and headers go out with the first write(), so there is always one, even for an empty body
// (ending a stream that was never written to drops them; see aws-lambda-nodejs-runtime-interface-client #97).
async function streamingBody(event, responseStream) {
  let out = null;
  const open = (statusCode, headers) => { if (!out) out = globalThis.awslambda.HttpResponseStream.from(responseStream, { statusCode, headers }); return out; };
  let r;
  try { r = await bufferedHandler(event, undefined, { start: open, write: (t) => out && out.write(t) }); }
  catch { if (out) { out.end(); return; } r = { statusCode: 500, headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" }, body: JSON.stringify({ error: "Something went wrong." }) }; }
  if (!r || !r.streamed) { open(r.statusCode, r.headers); out.write(r.body || ""); }
  out.end();
  if (typeof out.finished === "function") await out.finished();
}
export const handler = globalThis.awslambda?.streamifyResponse ? globalThis.awslambda.streamifyResponse(streamingBody) : streamingBody;
export const streamingHandler = handler;
